<script setup lang="ts">
import {apiError} from './apiError';
import AnalysisResultFrame from './AnalysisResultFrame.vue';
import {ref,watch,computed} from 'vue';
const props=defineProps<{module:string;projectId:string;section?:string}>();
const emit=defineEmits<{integration:[module:string]}>();
const planningVisible=computed(()=>Object.entries(planningFields).filter(([key])=>tab.value==='候选资源'?key.includes('unit')||key.startsWith('max_'):tab.value==='目标与约束'?!key.includes('unit')&&!key.startsWith('max_'):false));
const verification=ref<any>(null);
async function verify(){const projectId=props.projectId;working.value=true;planError.value='';try{const r=await fetch('/api/plans/'+plan.value.id+'/verify',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));if(props.projectId===projectId)verification.value=d}catch(e){planError.value=String(e)}finally{working.value=false}}
const runs=ref<any[]>([]);const runId=ref('');const plan=ref<any>(null);const working=ref(false);const planError=ref('');const planning=ref({storage_power_unit_kw:100,storage_energy_unit_kwh:200,max_storage_units:10,max_emergency_units:10,max_mobile_units:5,emergency_gen_unit_kw:100,mobile_unit_kw:100,storage_power_cost:600,storage_energy_cost:900,emergency_gen_cost:450,mobile_resource_cost:200000,penalty_energy_deficit:20,penalty_power_deficit:100,penalty_curtailment:2,default_soc_reserve_ratio:.35});
const planningFields:Record<string,string>={storage_power_unit_kw:"储能功率单元 / kW",storage_energy_unit_kwh:"储能能量单元 / kWh",emergency_gen_unit_kw:"应急发电单元 / kW",mobile_unit_kw:"移动资源单台功率 / kW",max_storage_units:"储能最大单元数",max_emergency_units:"应急电源最大单元数",max_mobile_units:"移动资源最大台数",storage_power_cost:"储能功率成本 / 元每kW",storage_energy_cost:"储能能量成本 / 元每kWh",emergency_gen_cost:"应急电源成本 / 元每kW",mobile_resource_cost:"移动资源成本 / 元每台",penalty_energy_deficit:"缺供电量惩罚 / 元每kWh",penalty_power_deficit:"功率缺额惩罚 / 元每kW",penalty_curtailment:"弃电惩罚 / 元每kWh",default_soc_reserve_ratio:"默认SOC预留比例"};
async function refreshRuns(){const projectId=props.projectId;runs.value=[];runId.value='';try{const r=await fetch('/api/runs?project_id='+encodeURIComponent(projectId));if(!r.ok)throw Error('无法读取计算记录');const data=await r.json();if(props.projectId!==projectId)return;runs.value=data;runId.value=data[0]?.id||''}catch{if(props.projectId===projectId)planError.value='无法读取计算记录'}}
async function calculate(){const projectId=props.projectId;working.value=true;planError.value='';plan.value=null;verification.value=null;try{const r=await fetch('/api/planning',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({run_id:runId.value,...planning.value})});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));if(props.projectId===projectId)plan.value=d}catch(e){planError.value=String(e)}finally{working.value=false}}
const schemas:Record<string,{tabs:string[],fields:[string,string,string][]}>={
'工程工作台':{tabs:['工程概览','数据准备','计算流程'],fields:[['工程名称','示范区工程','text'],['工程类型','村镇级','text'],['所属省份','新疆','text'],['研究区域','待录入','text'],['基准年份','2026','number'],['工程负责人','','text']]},
'数据管理':{tabs:['电网数据','电源与储能','负荷与经济参数'],fields:[['节点编号','N01','text'],['节点名称','','text'],['电压等级 / kV','10','number'],['经度','','number'],['纬度','','number'],['线路额定容量 / MVA','2.5','number'],['电源类型','分布式光伏','text'],['负荷分类','基本保障负荷','text'],['投资上限 / 万元','1800','number']]},
'保供场景生成':{tabs:['场景定义','故障与恢复','保供目标'],fields:[['场景名称','冬季雨雪冰冻','text'],['灾害类型','雨雪冰冻','text'],['季节','冬季','text'],['开始时间','2026-01-05T00:00','datetime-local'],['持续时间 / h','48','number'],['抢修时间 / h','24','number'],['故障线路编号','','text'],['场景权重','1','number'],['重要负荷最低满足率 / %','95','number'],['居民负荷最低满足率 / %','85','number']]},
'承灾极限分析':{tabs:['分析设置','承灾边界','薄弱环节'],fields:[['灾害强度基准说明','','text'],['扫描起始 / pu','0.2','number'],['扫描终止 / pu','1.5','number'],['扫描步长 / pu','0.05','number'],['目标保供时长 / h','48','number'],['最大允许缺电比例 / %','5','number'],['随机模拟次数','1000','number'],['置信水平 / %','95','number']]},
'源储协同配置':{tabs:['候选资源','目标与约束','规划阶段','配置结果'],fields:[['候选电源节点','N03,N09','text'],['候选储能节点','N07','text'],['储能功率上限 / kW','1000','number'],['储能容量上限 / kWh','2000','number'],['优化目标','经济性与保供综合','text'],['近期年份','2028','number'],['中期年份','2030','number'],['总投资上限 / 万元','1800','number']]},
'离网稳定判别':{tabs:['判别对象','扰动与阈值','风险结果'],fields:[['孤岛编号','ISLAND-01','text'],['孤岛节点范围','','text'],['扰动类型','外部电源中断','text'],['最低频率 / Hz','49.5','number'],['最低节点电压 / pu','0.9','number'],['最低短路比','2.5','number'],['最低惯量 / s','3','number'],['目标保供时长 / h','48','number']]},
'黑启动路径优化':{tabs:['恢复分区','启动资源','一二次约束','恢复序列'],fields:[['恢复区域','','text'],['黑启动电源编号','','text'],['初始SOC / %','80','number'],['目标恢复时间 / min','60','number'],['开关布点方案','','text'],['可用自动化终端','','text'],['可用通信路由','','text'],['励磁涌流限值 / A','','number'],['最大频率偏差 / Hz','0.5','number']]}}
const tab=ref('');
const fieldGroups:Record<string,number[][]>={
'工程工作台':[[0,1,2,3,4,5],[],[]], '数据管理':[[0,1,2,3,4,5],[6],[7,8]],
'保供场景生成':[[0,1,2,3,4,7],[5,6],[8,9]], '承灾极限分析':[[0,1,2,3,4,5,6,7],[],[]],
'源储协同配置':[[0,1,2,3],[4,7],[5,6],[]], '离网稳定判别':[[0,1,2],[3,4,5,6,7],[]],
'黑启动路径优化':[[0],[1,2],[3,4,5,6,7,8],[]]};
const visibleFields=computed(()=>{const schema=schemas[props.module];const index=schema.tabs.indexOf(tab.value);return fieldGroups[props.module][index].map(i=>schema.fields[i])});
const values=ref<Record<string,string>>({});const saved=ref('');const error=ref('');
async function read(){if(props.module==='源储协同配置')refreshRuns();const name=props.module;const projectId=props.projectId;const schema=schemas[name];tab.value=schema.tabs[0];values.value=Object.fromEntries(schema.fields.map(([k,v])=>[k,v]));saved.value='';try{const r=await fetch('/api/drafts/'+encodeURIComponent(name)+'?project_id='+encodeURIComponent(projectId));if(!r.ok)throw Error('无法读取草稿');const d=await r.json();if(props.module!==name||props.projectId!==projectId)return;if(d.values)values.value=d.values;error.value=''}catch(e){if(props.module===name&&props.projectId===projectId)error.value=String(e)}}
async function save(){try{const r=await fetch('/api/drafts/'+encodeURIComponent(props.module)+'?project_id='+props.projectId,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:values.value})});if(!r.ok)throw Error('保存失败');const d=await r.json();saved.value='已保存本机数据库 · '+d.updated;error.value=''}catch(e){error.value=String(e)}}
function download(){const blob=new Blob([JSON.stringify({module:props.module,values:values.value,status:'draft'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=props.module+'草稿.json';a.click();URL.revokeObjectURL(url)}
watch(()=>[props.module,props.projectId],()=>{plan.value=null;verification.value=null;read()},{immediate:true});
watch(()=>props.section,value=>{if(value&&schemas[props.module].tabs.includes(value))tab.value=value},{immediate:true});
</script>
<template><article v-if="module==='离网稳定判别'" class="notice"><h3>动态模型与验证资料：暂未交付</h3><p>已按用户要求保留为空。动态方程、训练权重和时域验证数据尚未导入；当前只保存参数草稿，不生成动态判稳或精度达标结果。</p></article><div class="module-tabs"><button v-for="t in schemas[module].tabs" :class="{current:tab===t}" @click="tab=t">{{t}}</button></div><div class="grid" v-if="module!=='源储协同配置'"><article><h3>{{tab}} / 参数草稿</h3><p v-if="visibleFields.length">此处可保存与导出需求参数，尚未提交到计算模型。</p><p v-else>此页用于后续展示{{tab}}，当前尚无对应结果。</p><label class="field" v-for="[key,,type] in visibleFields">{{key}}<input v-model="values[key]" :type="type" step="any"></label><div class="actions"><button class="primary" @click="save">保存草稿</button><button @click="download">导出 JSON</button><button @click="emit('integration',module)">前往模块交接接口</button></div><p>{{saved}}</p><p class="error" v-if="error">{{error}}</p></article><article><h3>当前配置摘要</h3><table><tr v-for="[key] in schemas[module].fields"><td>{{key}}</td><td>{{values[key]||'未填写'}}</td></tr></table><p class="notice">{{module==='工程工作台'?'工程信息保存在本地数据库草稿中，按当前所选工程分别管理。':module==='源储协同配置'?'研究代码包含简化规划算法，可在下方独立试算；本草稿尚未映射到该算法。':'参数页面已建立。结果区域保留待计算状态，不以示例数值代替计算结论。'}}</p><h3 v-if="module!=='源储协同配置'">结果与校核</h3><div v-if="module!=='源储协同配置'" class="pending-result"><span>—</span><p>尚无本模块计算结果</p></div></article></div><AnalysisResultFrame v-if="module!=='源储协同配置'" :module="module" :tab="tab"/><article v-if="module==='源储协同配置'"><h3>课题2简化规划试算</h3><p>使用已保存平衡结果，以及“候选资源”和“目标与约束”中设置的参数。枚举算法按经验系数估计残余缺额，不表示已通过时序或网络复核。</p><p v-if="tab==='规划阶段'" class="notice">当前原代码是单阶段枚举试算，不支持多阶段机会约束优化。近中远期源荷在“保供场景生成”分别归档；正式分阶段配置算法仍待接入，此页不生成虚构阶段方案。</p><label class="field">基准计算<select v-model="runId"><option v-for="r in runs" :value="r.id">{{r.created}} · {{r.id.slice(0,8)}}</option></select></label><div class="grid"><label class="field" v-for="[key,label] in planningVisible">{{label}}<input type="number" min="0" step="any" v-model.number="planning[key as keyof typeof planning]" :disabled="working"></label></div><p>成本与惩罚系数沿用研究模型口径，未年化；不能解释为项目全寿命经济性。数量上限直接限定枚举范围，移动资源缺少接入时序时不能进行自动复核。</p><button @click="calculate" :disabled="working||!runId||tab==='规划阶段'">{{working?'枚举计算中…':'执行简化规划'}}</button><p v-if="!runId">请先在电力电量平衡页面完成一次计算。</p><p class="error" v-if="planError">{{planError}}</p><div v-if="plan"><p>已评估 {{plan.candidate_count}} 个候选组合。成本单位为元，按本次保存的参数计算。</p><table><tr><th>建议储能功率 / kW</th><th>建议储能容量 / kWh</th><th>应急电源 / kW</th><th>移动资源 / 台</th><th>估计投资 / 元</th></tr><tr><td>{{plan.recommended_plan.storage_power_kw}}</td><td>{{plan.recommended_plan.storage_energy_kwh}}</td><td>{{plan.recommended_plan.emergency_gen_kw}}</td><td>{{plan.recommended_plan.mobile_units}}</td><td>{{plan.evaluation.investment_cost}}</td></tr></table><button @click="verify" :disabled="working||plan.recommended_plan.mobile_units>0">按新增资源进行真实时序复核</button><p v-if="plan.recommended_plan.mobile_units>0">建议包含移动资源，尚未提供位置和接入时序。可将移动资源最大台数设为0后重算固定资源方案。</p><p v-if="verification">{{verification.interpretation}}</p><table v-if="verification"><tr><th>指标</th><th>基准</th><th>复核</th></tr><tr><td>最大功率缺额 / kW</td><td>{{verification.baseline.max_power_deficit_kw.toFixed(2)}}</td><td>{{verification.verified.max_power_deficit_kw.toFixed(2)}}</td></tr><tr><td>缺供电量 / kWh</td><td>{{verification.baseline.expected_energy_deficit_kwh.toFixed(2)}}</td><td>{{verification.verified.expected_energy_deficit_kwh.toFixed(2)}}</td></tr></table><a v-if="verification" :href="'/api/runs/'+verification.run_id+'/report'">导出复核报告</a><details><summary>查看算法参数与完整结果</summary><pre>{{JSON.stringify(plan,null,2)}}</pre></details></div></article></template>
<style scoped>.module-tabs{display:flex;gap:8px;margin-top:22px;border-bottom:1px solid #cbdfe1;padding-bottom:12px}.current{background:#087b7b;color:white}.field{gap:20px}.field input{width:52%;min-width:120px}.pending-result{text-align:center;padding:35px;background:#f3f8f8;color:#81999c}.pending-result span{font-size:40px}.actions .primary{width:auto;margin:0}td{font-size:12px}</style>
